mapper.select:
SELECT id, title, type, amount, payee_name as payeeName, account, info, verify_state as verifyState, verify_staff as verifyStaffId, verify_time as verifyTime, verify_remark as verifyRemark, creator, add_time as addTime FROM cashout WHERE deleted = 0
AND creator = #{creator}
AND verify_state = #{verifyState}
AND DATE(add_time) >= #{startDate}
AND DATE(add_time) <= #{endDate}
ORDER BY add_time DESC
